    if len(sc)<2*k: return "need more entries"
    a=sum(sc[-k:])/k; b=sum(sc[-2*k:-k])/k
    return "improving" if a>b else "declining" if a<b else "steady"
def main():
    sc=[]
    for l in sys.stdin:
        if l.strip():
            s=score(l); sc.append(s); print(s,l.strip())
    if sc: print("avg %.2f | trend: %s"%(sum(sc)/len(sc),trend(sc)))
if __name__=="__main__": main()
