NEGATE={"not","never","no"}
def score(t):
    w=re.findall(r"[a-z']+",t.lower()); s=0
    for i,x in enumerate(w):
        v=(x in POS)-(x in NEG)
        if i and w[i-1] in NEGATE: v=-v
        s+=v
    return s
def trend(sc,k=3):
    if len(sc)<2*k: return "need more entries"
    a=sum(sc[-k:])/k; b=sum(sc[-2*k:-k])/k
    return "improving" if a>b else "declining" if a<b else "steady"
def themes(lines,n=3):
    from collections import Counter
    stop={"i","the","a","and","to","of","today","feeling","not","is","was","my","it"}
    c=Counter(x for l in lines for x in re.findall(r"[a-z']+",l.lower()) if x not in stop and len(x)>2)
    return [w for w,_ in c.most_common(n)]
